'use strict';
(()=>{
 const THEMES=[{id:'sakura',name:'Sakura',desc:'Hoa dưới ánh trăng'},{id:'grid',name:'Lưới sáng',desc:'Tương tác theo con trỏ'},{id:'gradient',name:'Tinh vân',desc:'Sắc màu chuyển chậm'},{id:'chrome',name:'Chrome',desc:'Ánh kim chuyển động'},{id:'still',name:'Tĩnh lặng',desc:'Nền tối, tập trung đọc'}];
 const defaults={landing:'sakura',study:'gradient',motion:true,brightness:45};
 let appearance;try{appearance={...defaults,...JSON.parse(localStorage.getItem('kienhoc-appearance-v1')||'{}')};}catch{appearance={...defaults};}
 for(const key of ['landing','study'])if(!THEMES.some(t=>t.id===appearance[key]))appearance[key]=defaults[key];
 appearance.motion=appearance.motion!==false;appearance.brightness=Math.max(15,Math.min(80,Number(appearance.brightness)||45));
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let backgroundRoot,canvas,dialog,metalHost,metal=null,disposeScene=()=>{},sceneKey='',titleDispose=()=>{},titlePlayed=false,titleToken=0;
 const icon=(name)=>{const paths={home:'<path d="m3 10 9-7 9 7v10H3V10Z"/><path d="M9 20v-7h6v7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',book:'<path d="M12 5C8 2 4 4 2 5v15c4-2 7-1 10 1 3-2 6-3 10-1V5c-4-2-7-3-10 0v16"/>',save:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',repeat:'<path d="M20 7h-6l3-4M4 17h6l-3 4M20 7a8 8 0 0 0-14-2M4 17a8 8 0 0 0 14 2"/>',palette:'<circle cx="12" cy="12" r="9"/><path d="m12 3 1 7 8 2M12 12l-7 6"/><circle cx="8" cy="7" r=".6"/><circle cx="6" cy="12" r=".6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',chart:'<path d="M4 20V4M4 20h17M9 16v-4M14 16V8M19 16V4"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;};
 const motionEnabled=()=>appearance.motion&&!reduced.matches;
 const scope=()=>view==='catalog'?'landing':'study';
 const persist=()=>{try{localStorage.setItem('kienhoc-appearance-v1',JSON.stringify(appearance));}catch{toast('Trình duyệt chưa lưu được tùy chọn giao diện.');}};
 function hero(){return `<section class="night-hero"><div class="night-hero-copy"><div class="night-eyebrow"><span></span> KHÔNG GIAN HỌC TẬP CỦA BẠN</div>${window.KienV9.wordmark()}<h2>Học có hướng.<br><em>Nhớ có cách.</em></h2><p>Chọn điều bạn muốn hiểu.<br>Biến từng câu hỏi thành một bước tiến.</p><div class="hero-actions"><a href="#course-library" class="academy-cta metal-primary">Khám phá môn học ${icon('arrow')}</a><button class="btn hero-theme" data-appearance>${icon('palette')} Góc học của tôi</button></div><div class="night-promises"><span>Không cần đăng ký</span><i></i><span>Miễn phí hiện tại</span></div></div>${window.KienV9.wheelMarkup()}</section>`;}
 const originalCatalog=catalogPage;
 catalogPage=function(){return originalCatalog().replace(/<section class="academy-hero">[\s\S]*?<\/section>/,hero());};
 function ensureUI(){
  if(backgroundRoot)return;
  document.body.classList.add('night-theme');
  backgroundRoot=document.createElement('div');backgroundRoot.id='scene-background';backgroundRoot.setAttribute('aria-hidden','true');backgroundRoot.innerHTML='<div class="ambient-moon"></div><div class="scene-css"></div><canvas></canvas><div class="scene-shade"></div>';document.body.prepend(backgroundRoot);canvas=backgroundRoot.querySelector('canvas');
  const mobile=document.createElement('div');mobile.className='mobile-topbar';mobile.innerHTML=`<button class="mobile-menu btn" data-menu-toggle aria-label="Mở mục lục" aria-expanded="false">${icon('menu')}</button><a class="mobile-brand" href="#" data-catalog>Kiến Học<span>GÓC HỌC CỦA BẠN</span></a><button class="btn" data-appearance aria-label="Tùy chỉnh giao diện">${icon('palette')}</button>`;document.body.prepend(mobile);
  const shade=document.createElement('button');shade.className='dock-backdrop';shade.dataset.closeDock='';shade.setAttribute('aria-label','Đóng mục lục');shade.tabIndex=-1;document.body.append(shade);
  const quick=document.createElement('div');quick.className='appearance-quick';quick.innerHTML=`<button class="btn" data-pause-motion aria-label="Tạm dừng hiệu ứng"></button><button class="btn" data-appearance>${icon('palette')}<span>Giao diện</span></button>`;document.body.append(quick);
  dialog=document.createElement('dialog');dialog.className='appearance-dialog';dialog.setAttribute('aria-labelledby','appearance-title');dialog.innerHTML=`<div class="appearance-heading"><div><span>PERSONAL SPACE</span><h2 id="appearance-title">Góc học, theo cách bạn.</h2></div><button class="btn" data-close-appearance aria-label="Đóng tùy chỉnh">${icon('close')}</button></div><p class="appearance-context"></p><div class="theme-choices">${THEMES.map(t=>`<button class="theme-choice" data-theme-choice="${t.id}" aria-pressed="false"><span class="theme-sample sample-${t.id}"><i></i><b>✓</b></span><strong>${t.name}</strong><small>${t.desc}</small></button>`).join('')}</div><div class="appearance-controls"><label class="motion-toggle"><span><b>Chuyển động</b><small>Ánh sáng, cánh hoa và hiệu ứng nút</small></span><input type="checkbox" id="appearance-motion" role="switch"></label><label class="brightness-control" for="appearance-brightness"><span>Độ sáng nền <output id="brightness-output"></output></span><input id="appearance-brightness" type="range" min="15" max="80" step="5"><small>Khung câu hỏi luôn giữ độ tương phản riêng.</small></label></div><div class="appearance-bottom"><span>Tự động ghi nhớ trên trình duyệt này.</span><button class="btn primary" data-close-appearance>Xong ${icon('check')}</button></div>`;document.body.append(dialog);
  dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  metalHost=document.createElement('div');metalHost.className='shared-metal-stage';metalHost.setAttribute('aria-hidden','true');metalHost.innerHTML='<canvas></canvas>';document.body.append(metalHost);
 }
 function gridScene(root,cv,settings){const ctx=cv.getContext('2d');if(!ctx)return()=>{};let raf=0,cells=[],width=0,height=0,stopped=false;const size=42;const resize=()=>{cancelAnimationFrame(raf);raf=0;width=root.clientWidth;height=root.clientHeight;const dpr=Math.min(devicePixelRatio||1,1.5);cv.width=width*dpr;cv.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw(performance.now());};function draw(now){raf=0;ctx.clearRect(0,0,width,height);ctx.strokeStyle='rgba(172,161,218,.09)';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<width;x+=size){ctx.moveTo(x,0);ctx.lineTo(x,height);}for(let y=0;y<height;y+=size){ctx.moveTo(0,y);ctx.lineTo(width,y);}ctx.stroke();cells=cells.filter(c=>now-c.t<1400);for(const c of cells){ctx.fillStyle=`rgba(${c.x%2?'145,115,207':'105,156,185'},${Math.sin(Math.min(1,(now-c.t)/1400)*Math.PI)*.3})`;ctx.fillRect(c.x*size+1,c.y*size+1,size-2,size-2);}if(cells.length&&settings.motion&&!document.hidden&&!stopped)raf=requestAnimationFrame(draw);}
  const move=e=>{if(!settings.motion||document.hidden)return;const x=Math.floor(e.clientX/size),y=Math.floor(e.clientY/size);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)if(cells.length<70&&!cells.some(c=>c.x===x+dx&&c.y===y+dy))cells.push({x:x+dx,y:y+dy,t:performance.now()});if(!raf)raf=requestAnimationFrame(draw);};const visibility=()=>{cancelAnimationFrame(raf);raf=0;if(!document.hidden)draw(performance.now());};const ro=new ResizeObserver(resize);ro.observe(root);window.addEventListener('pointermove',move,{passive:true});document.addEventListener('visibilitychange',visibility);resize();return()=>{stopped=true;cancelAnimationFrame(raf);ro.disconnect();window.removeEventListener('pointermove',move);document.removeEventListener('visibilitychange',visibility);};
 }
 function applyAppearance(){ensureUI();window.KienPolish?.motionChanged();const theme=appearance[scope()],motion=motionEnabled();document.body.dataset.scene=theme;document.body.classList.toggle('motion-paused',!motion);backgroundRoot.style.setProperty('--scene-brightness',appearance.brightness/100);if(!motion){titleToken++;titleDispose();titleDispose=()=>{};document.querySelector('.particle-wordmark')?.classList.remove('particle-ready');metal?.destroy();metal=null;}const key=theme+'|'+motion;
  if(sceneKey!==key){disposeScene();disposeScene=()=>{};sceneKey=key;const fresh=document.createElement('canvas');canvas.replaceWith(fresh);canvas=fresh;try{if(theme==='sakura')disposeScene=window.KienScenes.sakura(backgroundRoot,canvas,{motion})||(()=>{});else if(theme==='chrome')disposeScene=window.KienScenes.chrome(backgroundRoot,canvas,{motion})||(()=>{});else if(theme==='grid')disposeScene=gridScene(backgroundRoot,canvas,{motion});}catch(error){console.warn('Scene fallback:',error.message);canvas.style.display='none';}}
  const selected=THEMES.find(t=>t.id===theme);document.querySelectorAll('[data-theme-choice]').forEach(b=>{const active=b.dataset.themeChoice===theme;b.setAttribute('aria-pressed',String(active));});dialog.querySelector('.appearance-context').textContent=(scope()==='landing'?'Trang khám phá':'Không gian học')+' · '+selected.name;dialog.querySelector('#appearance-motion').checked=appearance.motion;dialog.querySelector('#appearance-motion').disabled=reduced.matches;dialog.querySelector('#appearance-brightness').value=appearance.brightness;dialog.querySelector('#brightness-output').textContent=appearance.brightness+'%';document.querySelectorAll('[data-pause-motion]').forEach(b=>{b.innerHTML=icon(motion?'pause':'play');b.setAttribute('aria-label',motion?'Tạm dừng hiệu ứng':'Bật hiệu ứng');b.setAttribute('aria-pressed',String(!motion));});if(reduced.matches)dialog.querySelector('.motion-toggle small').textContent='Đang theo cài đặt giảm chuyển động của thiết bị.';
 }
 function dockShell(){
  const history=!['catalog','subject'].includes(view),wrong=CORE.filter(q=>saved.progress[q.key]?.last===false).length,bookmarks=saved.bookmarks.filter(k=>BYKEY[k]).length;
  const nav=(label,i,attr,active,badge='',tone='silver')=>`<button class="nav dock-item ${active?'active':''}" ${attr} ${active?'aria-current="page"':''}><span class="dock-icon tone-${tone}">${icon(i)}</span><span class="dock-label">${label}</span>${badge}</button>`;
  const aside=document.querySelector('.sidebar');aside.id='learning-dock';aside.setAttribute('aria-label','Mục lục học tập');
  aside.innerHTML=`<div class="dock-heading"><a href="#" class="brand" aria-label="Kiến Học, thư viện môn học"><span class="brandmark">K</span><span>Kiến Học<small>Không gian học tập</small></span></a><button class="dock-hide" data-dock-toggle aria-label="Ẩn thanh mục lục" aria-controls="learning-dock" aria-expanded="true">${icon('close')}</button></div><div class="navlabel">KHÁM PHÁ</div><nav aria-label="Điều hướng học tập"><span class="dock-indicator" aria-hidden="true"></span>${nav('Thư viện môn học','home','data-catalog-nav',view==='catalog','','violet')}${nav('Tìm kiếm môn','search','data-find-subject',false,'','blue')}${saved.session?nav('Tiếp tục lượt ôn','play','id="resume"',view==='quiz','','mint'):''}<div class="dock-separator"></div><span class="dock-group-label">${history?esc(subjectTitle().toUpperCase()):'MÔN HỌC'}</span>${history?'':SUBJECTS.map(s=>nav(s.title,s.id==='ai'?'spark':s.id==='information'?'chart':'book',`data-course="${s.id}"`,view==='subject'&&activeSubject===s.id,'',s.id==='history'?'rose':s.id==='ai'?'violet':'mint')).join('')}<div class="history-links" ${history?'':'hidden'}>${nav('Tổng quan môn','book','data-view="home"',view==='home','','rose')}${nav('Ngân hàng câu hỏi','search','data-view="bank"',view==='bank',`<b>${CORE.length}</b>`,'blue')}${nav('Câu cần ôn lại','repeat','data-view="wrong"',view==='wrong',`<b id="wrong-count">${wrong}</b>`,'amber')}${nav('Đã đánh dấu','save','data-view="saved"',view==='saved',`<b id="saved-count">${bookmarks}</b>`,'violet')}${nav('Lộ trình & lưu ý','chart','data-view="guide"',view==='guide','','mint')}</div></nav><div class="sidebar-bottom">${nav('Góc học của tôi','palette','data-appearance',false)}<small>Tiến độ lưu trên trình duyệt này.</small></div>`;
  document.querySelector('header').innerHTML=`<div class="night-breadcrumb"><span>KHÔNG GIAN HỌC TẬP</span><strong>${view==='catalog'?'Khám phá điều mới':view==='subject'?esc(SUBJECTS.find(s=>s.id===activeSubject).title):esc(subjectTitle())}</strong></div><div class="header-actions"><label class="subject-switch"><span class="sr-only">Đổi môn học</span><select id="subject-switch" aria-label="Đổi môn học">${SUBJECTS.map(s=>`<option value="${s.id}" ${s.id===currentSubject?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><span class="live-label"><i></i> Theo nhịp của bạn</span><button class="btn" data-appearance>${icon('palette')} Giao diện</button></div>`;
  document.body.classList.remove('dock-open');document.querySelector('[data-menu-toggle]').setAttribute('aria-expanded','false');
 }
 function animateTitle(){titleDispose();titleDispose=()=>{};const token=++titleToken,word=document.querySelector('.particle-wordmark');if(!word||titlePlayed||!motionEnabled())return;titlePlayed=true;const cv=word.querySelector('canvas');Promise.resolve(document.fonts?.ready).then(()=>{if(token!==titleToken||!cv.isConnected||!motionEnabled())return;const engine=window.KienScenes.particle(cv,'Kiến Học');if(!engine)return;word.classList.add('particle-ready');const sync=()=>engine.setActive(!document.hidden),observer=new IntersectionObserver(([e])=>engine.setActive(e.isIntersecting&&!document.hidden));observer.observe(cv);const resizeObserver=new ResizeObserver(()=>engine.resize());resizeObserver.observe(word);document.addEventListener('visibilitychange',sync);titleDispose=()=>{observer.disconnect();resizeObserver.disconnect();word.classList.remove('particle-ready');document.removeEventListener('visibilitychange',sync);engine.destroy();};});}
 function afterRender(){ensureUI();metal?.destroy();metal=null;metalHost.style.opacity='0';dockShell();window.KienAuth?.refresh();applyAppearance();animateTitle();window.KienPolish?.afterRender();}
 function closeDock(){document.body.classList.remove('dock-open');document.querySelector('[data-menu-toggle]').setAttribute('aria-expanded','false');}
 function openAppearance(){metal?.leave();metal?.blur();applyAppearance();if(!dialog.open)dialog.showModal();}
 document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t||t.disabled)return;if(t.hasAttribute('data-menu-toggle')){const open=document.body.classList.toggle('dock-open');t.setAttribute('aria-expanded',String(open));}else if(t.hasAttribute('data-close-dock'))closeDock();else if(t.hasAttribute('data-appearance'))openAppearance();else if(t.hasAttribute('data-close-appearance'))dialog.close();else if(t.hasAttribute('data-pause-motion')){appearance.motion=!appearance.motion;persist();applyAppearance();}else if(t.dataset.themeChoice){appearance[scope()]=t.dataset.themeChoice;persist();applyAppearance();}else if(t.hasAttribute('data-find-subject')){go('catalog');requestAnimationFrame(()=>{const input=document.querySelector('#subject-search');input?.scrollIntoView({block:'center'});input?.focus();});}},true);
 document.addEventListener('input',e=>{if(e.target.id==='appearance-brightness'){appearance.brightness=Number(e.target.value);backgroundRoot.style.setProperty('--scene-brightness',appearance.brightness/100);dialog.querySelector('#brightness-output').textContent=appearance.brightness+'%';persist();}});
 document.addEventListener('change',e=>{if(e.target.id==='appearance-motion'){appearance.motion=e.target.checked;persist();applyAppearance();}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDock();});reduced.addEventListener('change',()=>{applyAppearance();metal?.destroy();metal=null;});
 const shaderSelector='.academy-cta,.btn.primary,.course-open';
 function bindMetal(t,focus=false){if(!t||t.disabled||t.closest('dialog')||!motionEnabled())return;if(!metal)try{metal=window.KienMetal.mount(metalHost,t,metalHost.querySelector('canvas'));}catch(error){console.warn('Metal fallback:',error.message);return;}if(focus)metal.focus(t);else metal.bind(t);}
 document.addEventListener('pointerover',e=>{if(e.pointerType&&e.pointerType!=='mouse')return;const t=e.target.closest(shaderSelector);if(t&&!t.contains(e.relatedTarget))bindMetal(t);});document.addEventListener('pointerout',e=>{const t=e.target.closest(shaderSelector);if(t&&!t.contains(e.relatedTarget))metal?.leave();});
 document.addEventListener('focusin',e=>{const t=e.target.closest(shaderSelector);if(t&&t.matches(':focus-visible'))bindMetal(t,true);});document.addEventListener('focusout',e=>{if(e.target.closest(shaderSelector))metal?.blur();});
 document.addEventListener('pointerdown',e=>{const t=e.target.closest(shaderSelector);if(t&&!t.disabled){bindMetal(t);metal?.press(t,e);}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat){const t=e.target.closest(shaderSelector);if(t&&!t.disabled){bindMetal(t,true);metal?.press(t);}}});document.addEventListener('keyup',e=>{if(e.key==='Enter'||e.key===' ')metal?.release();});
 window.KienUI={afterRender,motionEnabled};
})();
